/*
 * A preview QR for the dev harness.
 *
 * Keycloakify's mock ships a 246x246 PNG with a 25px quiet zone baked into each side, so
 * roughly a fifth of it is white border and it read as badly over-padded on the card. This
 * is that same image cropped back to the code plus a hairline margin (3% of the code), so
 * the preview shows it at the size and with the slight border the design has.
 *
 * IMPORTANT: this only fixes the preview. In production totp.totpSecretQrCode is a real QR
 * generated by Keycloak and carries the full quiet zone, so the card will show a wider white
 * margin there than the designs do. Fixing that for real means either trimming the image at
 * runtime or accepting the border - see the README.
 */
export const PREVIEW_QR_CODE_BASE64 =
  "";